  const cards = (metrics = [], evidenceKey = '') => `<div class="employee-kpi-metrics">${metrics.map((m) => { const help=metricHelp[m.label]||m.explanation||''; const missing=m.value===null||m.value===undefined; return `<article class="kpi-health-card ${missing?'is-unmeasured':''}"><span>${esc(m.label)}${help?` <button type="button" class="kpi-info-button" title="${esc(help)}" aria-label="About ${esc(m.label)}" data-kpi-help="${esc(help)}">i</button>`:''}</span><strong class="kpi-number">${esc(value(m))}</strong><small>${m.denominator !== undefined&&m.denominator !== null ? `${esc(m.numerator??m.value)} of ${esc(m.denominator)} eligible records` : esc(missing ? (m.status==='not_applicable'?'Not applicable to this role':'Insufficient historical data') : (m.explanation||''))}</small>${m.source?`<small>Source: ${esc(m.source)}</small>`:''}${evidenceKey?`<button type="button" class="kpi-view-evidence" data-kpi-evidence-section="${esc(evidenceKey)}">View Evidence</button>`:''}</article>`; }).join('')}</div>`;
