  function distribution(rows=[], field='result') { const counts=new Map(); rows.forEach(row=>{const label=normalise(row[field]||'Awaiting review');counts.set(label,(counts.get(label)||0)+1);}); const total=rows.length||1; return `<div class="kpi-distribution" role="img" aria-label="${rows.length} eligible records">${[...counts.entries()].map(([label,count],index)=>`<div class="kpi-distribution__row"><span>${esc(label.replaceAll('_',' '))}</span><div><i style="--kpi-bar:${Math.max(2,count/total*100)}%;--kpi-bar-index:${index}"></i></div><strong>${count} <small>${(count/total*100).toFixed(0)}%</small></strong></div>`).join('')||'<p>No eligible work in this period.</p>'}</div>`; }
  const table = (columns, rows = []) => formatElapsedHtml(`<div class="employee-kpi-evidence"><table class="data-table"><thead><tr>${columns.map((c) => `<th>${esc(c[0])}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.map((row) => `<tr>${columns.map((c) => `<td>${c[2] ? c[2](row[c[1]], row) : esc(row[c[1]] ?? '—')}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${columns.length}">No measured records in this period.</td></tr>`}</tbody></table></div>`);
