  const presenceSummaryHtml = (summary={}) => `<div class="kpi-presence-groups"><section><h3>Live Presence</h3><p>Uses the same heartbeat and 120-second online rule as the portal header.</p><div class="kpi-presence-summary"><article><span>Live status</span><strong data-live-state>${summary.currently_online?'<i class="kpi-presence-pulse"></i> Online':'Offline'}</strong></article><article><span>Current session</span><strong data-live-start>${date(summary.current_session_started)}</strong><small data-live-duration>${summary.currently_online?duration(summary.current_session_duration_seconds):'No active session'}</small></article><article><span>Current page</span><strong data-live-page>Awaiting heartbeat</strong><small data-live-seen>Last seen unavailable</small></article><article><span>Live refresh</span><strong data-live-refreshed>Refreshing…</strong><small>Updates every 30 seconds</small></article></div><div data-live-diagnostic></div></section><section><h3>Historical Sessions</h3><p>Authenticated and workflow evidence for the selected reporting period; it is not live status.</p><div class="kpi-presence-summary"><article><span>Last historical activity</span><strong>${date(summary.last_portal_activity)}</strong></article><article><span>Authenticated sessions</span><strong>${Number(summary.total_sessions||0)}</strong><small>${durationMinutes(Number(summary.authenticated_session_hours||0)*60)} session presence</small></article><article><span>Portal-active time</span><strong>${durationMinutes(Number(summary.portal_active_hours||0)*60)}</strong><small>Supporting evidence only</small></article><article><span>Workflow actions</span><strong>${Number(summary.workflow_actions||0)}</strong></article></div></section><section><h3>Schedule Compliance</h3><p>${summary.scheduled_days?'Measured only against configured schedule days.':'No schedule is configured. Schedule compliance is not measured and does not reduce this score.'}</p>${summary.scheduled_days?'':`<a class="btn-secondary" href="reports.php?tab=settings#attendance">Configure Schedule</a>`}<div class="kpi-presence-summary"><article><span>Scheduled days</span><strong>${Number(summary.scheduled_days||0)}</strong></article><article><span>Evidence-covered days</span><strong>${Number(summary.evidence_covered_days||0)}</strong></article><article><span>Days requiring review</span><strong>${Number(summary.days_requiring_review||0)}</strong><small>${esc(summary.status||'provisional')}</small></article><article><span>Schedule compliance</span><strong>${summary.portal_schedule_compliance===null||summary.portal_schedule_compliance===undefined?'Not measured':`${Number(summary.portal_schedule_compliance).toFixed(1)}%`}</strong></article></div></section></div>`;
