    if(key==='packing'&&data.front_packing_list_kpi){heading='Live Website Updates';explanation='Front-person website-update timeliness and completion evidence.';}
    if(key==='tasks'&&data.task_management_performance){heading='Task Performance';explanation='Outcomes, deadlines and required process compliance.';}
